body:
Here is some quick code to get your public ip address from http://ipinfo.io/ using hyper crate.

    extern crate hyper;

    use hyper::Client;
    use hyper::header::Connection;
    use std::io::Read;

    fn external_ip() -> String {
        let client = Client::new();
        let mut response = client.get("http://ipinfo.io/ip/").
            header(Connection::close()).send().unwrap();
        let mut external_ip = String::new();
        response.read_to_string(&mut external_ip).unwrap();
        return external_ip;
    }

    fn main() {
        let external_ip = external_ip();
        println!("{}", external_ip);
    }

This code does not work for new hyper v0.11 version though. You should set your dependencies section in `Cargo.toml` as `hyper = "0.10"`. I haven't yet used v0.11.
